#include <stdio.h>
int main(void) {
    printf("%d %d %d %d\n", 7 / 2, -7 / 2, 7 % 2, -7 % 2);
    int x = 5;
    x += 3;  x *= 2;
    int y = x++;            /* y gets the old value */
    printf("x=%d y=%d\n", x, y);
    printf("%s\n", x > 10 ? "big" : "small");
    int n = 2;
    switch (n) {
    case 1: printf("one\n");
    case 2: printf("two\n");
    case 3: printf("three\n"); break;
    default: printf("other\n");
    }
    for (int i = 0; i < 3; i++) printf("for %d\n", i);
    int k = 3;
    while (k > 0) k--;      /* test first, then run the body */
    do { k++; } while (k < 2);  /* body runs at least once */
    printf("k=%d\n", k);
    return 3;
}
/* Output:
3 -3 1 -1
x=17 y=16
big
two
three
for 0
for 1
for 2
k=2
and the exit status (echo $?) is 3 */

