#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int *v = NULL;
    size_t len = 0, cap = 0;
    for (int i = 1; i <= 5; i++) {
        if (len == cap) {
            size_t ncap = cap ? cap * 2 : 2;
            int *nv = realloc(v, ncap * sizeof *nv);
            if (!nv) { free(v); return 1; }
            v = nv;
            cap = ncap;
        }
        v[len++] = i * 10;
    }
    printf("len=%zu cap=%zu last=%d\n", len, cap, v[len - 1]);
    free(v);
    return 0;
}

blocks.md:
A point on a screen has two coordinates. Passing x and y around as separate ints works until you have a hundred points. A *struct* groups named members into one type:

```
struct point { int x; int y; };
struct point a = { 1, 2 };
```

Now `a.x` is 1 and `a.y` is 2. The dot operator `.` selects a member. Structs are how C builds every record and every data structure.

blocks.code:
#include <stdio.h>

struct point { int x; int y; };
typedef struct point point;      /* point now means struct point */

void move_copy(point p) { p.x += 10; }
void move_ptr(point *p) { p->x += 10; }   /* same as (*p).x += 10 */

int main(void) {
    point a = { .x = 1, .y = 2 };
    point b = a;                 /* copies every member */
    b.y = 99;
    move_copy(a);
    printf("after move_copy: a = (%d, %d)\n", a.x, a.y);
    move_ptr(&a);
    printf("after move_ptr:  a = (%d, %d), b = (%d, %d)\n", a.x, a.y, b.x, b.y);
    point z = { .y = 5 };        /* members not named are zero */
    printf("z = (%d, %d)\n", z.x, z.y);
    return 0;
}
/* Output:
after move_copy: a = (1, 2)
after move_ptr:  a = (11, 2), b = (1, 99)
z = (0, 5) */

#include <stdio.h>
#include <stdlib.h>

typedef struct node {
    int value;
    struct node *next;          /* NULL in the last node */
} node;

int push_front(node **head, int value) {
    node *n = malloc(sizeof *n);
    if (!n) return -1;
    n->value = value;
    n->next = *head;            /* new node points at the old first */
    *head = n;                  /* caller's head now points at it */
    return 0;
}

void print_list(const node *head) {
    for (const node *n = head; n; n = n->next)
        printf("%d ", n->value);
    printf("\n");
}

void free_list(node *head) {
    while (head) {
        node *next = head->next;   /* save the link first */
        free(head);
        head = next;
    }
}

void remove_value(node **head, int value) {
    for (node **pp = head; *pp; pp = &(*pp)->next) {
        if ((*pp)->value == value) {
            node *dead = *pp;
            *pp = dead->next;      /* the link that pointed at dead skips it */
            free(dead);
            return;
        }
    }
}

int main(void) {
    node *head = NULL;
    for (int v = 1; v <= 3; v++)
        if (push_front(&head, v * 10) != 0) return 1;
    print_list(head);            /* 30 20 10 */
    remove_value(&head, 20);
    print_list(head);            /* 30 10 */
    remove_value(&head, 30);     /* removing the first node: no special case */
    print_list(head);            /* 10 */
    free_list(head);
    return 0;
}

