#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct { const char *name; int stock; } item;

int by_stock(const void *a, const void *b) {
    const item *x = a, *y = b;          /* void * converts back */
    return (x->stock > y->stock) - (x->stock < y->stock);
}

int by_name(const void *a, const void *b) {
    const item *x = a, *y = b;
    return strcmp(x->name, y->name);
}

void show(const item *v, size_t n) {
    for (size_t i = 0; i < n; i++) printf("%s:%d ", v[i].name, v[i].stock);
    printf("\n");
}

int main(void) {
    item v[] = { {"pear", 7}, {"fig", 42}, {"kiwi", 3}, {"plum", 19} };
    size_t n = sizeof v / sizeof v[0];
    int (*cmp)(const void *, const void *) = by_stock;
    qsort(v, n, sizeof v[0], cmp);
    show(v, n);                    /* kiwi:3 pear:7 plum:19 fig:42 */
    cmp = by_name;
    qsort(v, n, sizeof v[0], cmp);
    show(v, n);                    /* fig:42 kiwi:3 pear:7 plum:19 */
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int cmp(const void *a, const void *b) {
    int x = *(const int *)a, y = *(const int *)b;
    printf("cmp(%d, %d)\n", x, y);
    return (x > y) - (x < y);
}

int main(void) {
    int v[] = { 7, 42, 3, 19 };
    qsort(v, 4, sizeof v[0], cmp);
    printf("%d %d %d %d\n", v[0], v[1], v[2], v[3]);
    return 0;
}

#include <stdio.h>
#include <string.h>

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "usage: %s FILE\n", argv[0]);
        return 2;
    }
    FILE *f = fopen(argv[1], "r");
    if (!f) {
        perror(argv[1]);
        return 1;
    }
    char buf[8];
    size_t lines = 0, cur = 0, longest = 0;
    while (fgets(buf, sizeof buf, f)) {
        size_t k = strlen(buf);
        int ended = k > 0 && buf[k - 1] == '\n';
        cur += ended ? k - 1 : k;
        if (ended) {
            lines++;
            if (cur > longest) longest = cur;
            cur = 0;
        }
    }
    if (cur > 0) {                  /* last line had no newline */
        lines++;
        if (cur > longest) longest = cur;
    }
    int failed = ferror(f);
    fclose(f);
    if (failed) {
        fprintf(stderr, "%s: read error\n", argv[1]);
        return 1;
    }
    printf("%zu lines, longest %zu chars\n", lines, longest);
    return 0;
}

