/* Returns 0 on success, -1 on failure; *copied gets the byte count. */
int copy_file(const char *from, const char *to, size_t *copied) {
    int status = -1;
    FILE *in = NULL, *out = NULL;
    size_t n, total = 0;
    char *buf = malloc(4096);
    if (!buf) goto done;
    in = fopen(from, "rb");
    if (!in) { fprintf(stderr, "%s: %s\n", from, strerror(errno)); goto done; }
    out = fopen(to, "wb");
    if (!out) { fprintf(stderr, "%s: %s\n", to, strerror(errno)); goto done; }
    while ((n = fread(buf, 1, 4096, in)) > 0) {
        if (fwrite(buf, 1, n, out) != n) goto done;
        total += n;
    }
    if (ferror(in)) goto done;
    *copied = total;
    status = 0;
done:                                  /* undo in reverse order */
    if (out && fclose(out) != 0) status = -1;
    if (in) fclose(in);
    free(buf);
    return status;
}

